with
fun outward($p: event) -> { event }:
  match
    { event-containment (containing-pathway: $p, contained-event: $e); } or
    { event-precedence (preceding-event: $e, following-event: $p); };
  return { $e };
with
fun reachable($p: event) -> { event }:
  match
    { let $e in outward($p); } or
    { let $m in outward($p);
      let $e in reachable($m); };
  return { $e };
match
  $root isa pathway, has st-id "R-HSA-168256";
  let $e in reachable($root);
  $e isa reaction-like-event;
select $e;
distinct;
reduce $count = count;

with
fun sub-events($p: event) -> { event }:
  match
    { event-containment (containing-pathway: $p, contained-event: $e); } or
    { event-containment (containing-pathway: $p, contained-event: $m);
      let $e in sub-events($m); };
  return { $e };
match
  $p isa pathway;
  species-assignment (classified-thing: $p, species: $sp);
  $sp has display-name "Homo sapiens";
  event-containment (containing-pathway: $p, contained-event: $r);
  $r isa reaction-like-event;
  not {
    event-containment (containing-pathway: $p, contained-event: $sub);
    $sub isa pathway;
    let $under in sub-events($sub);
    $under is $r;
  };
select $p;
distinct;
reduce $count = count;

with
fun sub-depths($p: event) -> { event, integer }:
  match
    { event-containment (containing-pathway: $p, contained-event: $e); let $d = 1; } or
    { event-containment (containing-pathway: $p, contained-event: $m);
      let $e, $d0 in sub-depths($m);
      let $d = $d0 + 1; };
  return { $e, $d };
match
  $root isa pathway, has st-id "R-HSA-168256";
  let $e, $d in sub-depths($root);
  $e isa reaction-like-event;
select $e, $d;
distinct;
reduce $shallowest = min($d) groupby $e;
reduce $avg = mean($shallowest);
match
  let $rounded = round($avg * 10000.0) / 10000.0;
select $rounded;

